var ENGINE = _global.getCurrentEngine();
var INTERFACE = _global.getCurrentInterface();
var start_x = 360;
var start_y = 300;
var SHELL = _global.getCurrentShell();
var language;
var localized_frame = 4;
if(SHELL.getLocalizedFrame != undefined)
{
   localized_frame = SHELL.getLocalizedFrame();
}
switch(localized_frame)
{
   case 1:
      language = "english";
      break;
   case 2:
      language = "portuguese";
      break;
   case 3:
      language = "french";
      break;
   case 4:
      language = "spanish";
      break;
   default:
      language = "english";
}
scafleg_mc.gotoAndStop(language);
minesign_mc.gotoAndStop(language);
background_mc.entrance_mc.caution_mc.gotoAndStop(language);
background_mc.pufflerescue_mc.gotoAndStop(language);
background_mc.noticeboard_mc.gotoAndStop(language);
triggers_mc.freeitem_mc.triggerFunction = function()
{
   INTERFACE.buyInventory(429);
};
triggers_mc.cave_mc.triggerFunction = function()
{
   ENGINE.sendJoinRoom("cave",622,360);
};
triggers_mc.cavedig_mc.triggerFunction = function()
{
   ENGINE.sendJoinRoom("cavemine",108,297);
};
triggers_mc.cart_mc.triggerFunction = function()
{
   ENGINE.sendJoinGame("cart",true);
};
triggers_mc.rescue_mc.triggerFunction = function()
{
   ENGINE.sendJoinGame("rescue",true);
};
background_mc.noticeboard_mc.pinboard_btn.onRelease = function()
{
   ENGINE.sendPlayerMove(300,200);
};
background_mc.noticeboard_mc.pinboard_btn.onRollOver = function()
{
   INTERFACE.showHint(this,"rescue_hint");
};
background_mc.noticeboard_mc.pinboard_btn.onRollOut = function()
{
   INTERFACE.closeHint();
};
cart_btn.onRelease = function()
{
   ENGINE.sendPlayerMove(630,200);
};
cart_btn.onRollOver = function()
{
   INTERFACE.showHint(this,"cart_hint");
};
cart_btn.onRollOut = function()
{
   INTERFACE.closeHint();
};
triggers_mc._visible = false;
block_mc._visible = false;
